css:
.win > .bar{background:linear-gradient(90deg, var(--tint), transparent)}.wall i{opacity:.55}
.sy-sun{position:absolute;left:50%;bottom:38%;width:260px;height:260px;margin-left:-130px;
  border-radius:50%;background:linear-gradient(#ffe14d,#ff3d9a 62%,#9d6bff);
  -webkit-mask:repeating-linear-gradient(#000 0 12px,transparent 12px 17px);
  mask:repeating-linear-gradient(#000 0 12px,transparent 12px 17px);
  filter:drop-shadow(0 0 44px rgba(255,61,154,.6));animation:syRise 9s ease-in-out infinite}
@keyframes syRise{0%,100%{bottom:36%}50%{bottom:40%}}
.sy-horizon{position:absolute;left:0;right:0;bottom:38%;height:2px;background:#34e7e4;
  box-shadow:0 0 22px 4px rgba(52,231,228,.75)}
.sy-grid{position:absolute;left:-50%;right:-50%;bottom:0;height:38%;
  background-image:repeating-linear-gradient(90deg,rgba(52,231,228,.55) 0 2px,transparent 2px 84px),
    repeating-linear-gradient(rgba(255,61,154,.5) 0 2px,transparent 2px 62px);
  transform:perspective(340px) rotateX(74deg);transform-origin:50% 100%;
  animation:syRun 2.4s linear infinite}
@keyframes syRun{to{background-position:0 62px, 0 62px}}
.sy-scan{position:absolute;inset:0;background:repeating-linear-gradient(rgba(0,0,0,.22) 0 2px,transparent 2px 5px)}
